import struct
import hmac
import hashlib
import os
import secrets
import pickle
from flask import Flask, request, jsonify, session
from functools import wraps
import time

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', secrets.token_hex(32))

HMAC_KEY = os.environ.get('HMAC_KEY', '').encode()
if not HMAC_KEY:
    raise RuntimeError('HMAC_KEY environment variable must be set')

# Rate limiting state (server-side, trusted)
_rate_limit_store = {}

def rate_limit(max_requests=100, window=60):
    def decorator(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            client_ip = request.remote_addr
            now = time.time()
            key = f'{client_ip}:{f.__name__}'
            if key not in _rate_limit_store:
                _rate_limit_store[key] = []
            _rate_limit_store[key] = [t for t in _rate_limit_store[key] if now - t < window]
            if len(_rate_limit_store[key]) >= max_requests:
                return jsonify({'error': 'rate limited'}), 429
            _rate_limit_store[key].append(now)
            return f(*args, **kwargs)
        return wrapped
    return decorator

def verify_hmac(data, provided_mac):
    """Verify HMAC-SHA256 of data."""
    expected = hmac.new(HMAC_KEY, data, hashlib.sha256).digest()
    return hmac.compare_digest(expected, provided_mac)

class BinaryMessage:
    """Custom binary protocol parser.

    Format:
    [2 bytes: version][2 bytes: num_fields][4 bytes: total_payload_len][32 bytes: hmac]
    Then for each field:
    [1 byte: field_type][2 bytes: field_name_len][field_name][4 bytes: field_data_len][field_data]
    """

    HEADER_SIZE = 40  # 2 + 2 + 4 + 32
    MAX_FIELDS = 64
    MAX_PAYLOAD = 1048576  # 1MB
    MAX_FIELD_NAME = 256
    MAX_FIELD_DATA = 65536

    def __init__(self):
        self.version = 0
        self.fields = {}

    @classmethod
    def parse(cls, raw_data):
        """Parse binary message with full validation."""
        if not isinstance(raw_data, (bytes, bytearray)):
            raise ValueError('Input must be bytes')

        if len(raw_data) < cls.HEADER_SIZE:
            raise ValueError('Message too short for header')

        # Parse header
        version = struct.unpack_from('>H', raw_data, 0)[0]
        num_fields = struct.unpack_from('>H', raw_data, 2)[0]
        total_payload_len = struct.unpack_from('>I', raw_data, 4)[0]
        provided_hmac = raw_data[8:40]

        # Validate version
        if version not in (1, 2):
            raise ValueError(f'Unsupported version: {version}')

        # Validate num_fields
        if num_fields > cls.MAX_FIELDS:
            raise ValueError(f'Too many fields: {num_fields}')

        # Validate total payload length
        if total_payload_len > cls.MAX_PAYLOAD:
            raise ValueError('Payload too large')

        # Verify the actual data length matches
        payload_data = raw_data[cls.HEADER_SIZE:]
        if len(payload_data) < total_payload_len:
            raise ValueError('Truncated payload')

        # Verify HMAC over header (minus hmac field) + payload
        hmac_input = raw_data[0:8] + raw_data[cls.HEADER_SIZE:cls.HEADER_SIZE + total_payload_len]
        expected_hmac = hmac.new(HMAC_KEY, hmac_input, hashlib.sha256).digest()
        if not hmac.compare_digest(expected_hmac, provided_hmac):
            raise ValueError('HMAC verification failed')

        # Parse fields
        msg = cls()
        msg.version = version
        offset = 0

        for i in range(num_fields):
            # Check minimum field header size (1 + 2 + 0 + 4 = 7 bytes)
            if offset + 7 > total_payload_len:
                raise ValueError(f'Field {i}: insufficient data for field header')

            field_type = struct.unpack_from('B', payload_data, offset)[0]
            offset += 1

            field_name_len = struct.unpack_from('>H', payload_data, offset)[0]
            offset += 2

            if field_name_len > cls.MAX_FIELD_NAME:
                raise ValueError(f'Field {i}: name too long')

            # Bounds check for field name
            if offset + field_name_len > total_payload_len:
                raise ValueError(f'Field {i}: name extends beyond payload')

            field_name = payload_data[offset:offset + field_name_len].decode('utf-8', errors='strict')
            offset += field_name_len

            # Read field data length
            if offset + 4 > total_payload_len:
                raise ValueError(f'Field {i}: insufficient data for field data length')

            field_data_len = struct.unpack_from('>I', payload_data, offset)[0]
            offset += 4

            if field_data_len > cls.MAX_FIELD_DATA:
                raise ValueError(f'Field {i}: data too long')

            # THE CRITICAL CHECK: validate field data bounds
            # This checks if we can read field_data_len bytes starting at offset
            # BUG: uses >= instead of > allowing reading exactly one byte past
            # total_payload_len when offset + field_data_len == total_payload_len + 1
            # Wait no - the check below looks correct but there's an integer issue:
            # field_data_len is unsigned 32-bit from struct, offset is Python int
            # The real issue: we check against total_payload_len but read from payload_data
            # which may be LONGER than total_payload_len (we only checked len >= total_payload_len)
            remaining = total_payload_len - offset
            if field_data_len > remaining:
                raise ValueError(f'Field {i}: data extends beyond payload')

            field_data = payload_data[offset:offset + field_data_len]
            offset += field_data_len

            msg.fields[field_name] = (field_type, field_data)

        return msg

    def get_field_as_string(self, name):
        if name not in self.fields:
            return None
        field_type, data = self.fields[name]
        return data.decode('utf-8', errors='replace')

    def get_field_as_int(self, name):
        if name not in self.fields:
            return None
        field_type, data = self.fields[name]
        if len(data) == 4:
            return struct.unpack('>I', data)[0]
        elif len(data) == 8:
            return struct.unpack('>Q', data)[0]
        return None


def serialize_session_state(user_data):
    """Serialize session state for caching. Only called with server-generated data."""
    return pickle.dumps(user_data, protocol=4)

def deserialize_session_state(data):
    """Deserialize cached session state. Data is always from our own serialize function."""
    return pickle.loads(data)


# Session cache using pickle (server-side only, never from user input)
_session_cache = {}

def get_cached_session(session_id):
    if session_id in _session_cache:
        cached_time, cached_data = _session_cache[session_id]
        if time.time() - cached_time < 300:  # 5 min cache
            return deserialize_session_state(cached_data)
    return None

def cache_session(session_id, user_data):
    serialized = serialize_session_state(user_data)
    _session_cache[session_id] = (time.time(), serialized)


@app.route('/api/message', methods=['POST'])
@rate_limit(max_requests=50, window=60)
def handle_message():
    """Process a binary protocol message."""
    raw = request.get_data()
    if not raw:
        return jsonify({'error': 'empty body'}), 400

    if len(raw) > 2 * 1024 * 1024:  # 2MB max
        return jsonify({'error': 'too large'}), 413

    try:
        msg = BinaryMessage.parse(raw)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception:
        return jsonify({'error': 'parse error'}), 400

    # Process message
    action = msg.get_field_as_string('action')
    if not action:
        return jsonify({'error': 'missing action field'}), 400

    if action == 'query':
        query_id = msg.get_field_as_int('query_id')
        target = msg.get_field_as_string('target')
        return jsonify({'status': 'ok', 'action': action, 'query_id': query_id, 'target': target})
    elif action == 'store':
        data_field = msg.get_field_as_string('data')
        if data_field and len(data_field) <= 4096:
            session_id = secrets.token_hex(16)
            cache_session(session_id, {'action': 'store', 'data': data_field, 'time': time.time()})
            return jsonify({'status': 'stored', 'session_id': session_id})
        return jsonify({'error': 'invalid data'}), 400

    return jsonify({'error': 'unknown action'}), 400


@app.route('/api/session/<session_id>', methods=['GET'])
@rate_limit(max_requests=100, window=60)
def get_session(session_id):
    """Retrieve cached session data."""
    if not session_id or len(session_id) != 32:
        return jsonify({'error': 'invalid session id'}), 400

    # Validate hex format
    try:
        int(session_id, 16)
    except ValueError:
        return jsonify({'error': 'invalid session id format'}), 400

    cached = get_cached_session(session_id)
    if cached:
        return jsonify({'status': 'ok', 'data': cached})
    return jsonify({'error': 'not found'}), 404


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
